import{_ as a,o as t,c as s,a3 as o}from"./chunks/framework.iy8UH-03.js";const g=JSON.parse('{"title":"Curated workouts are catalog items at three levels","description":"","frontmatter":{"status":"accepted","date":"2026-11-22T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0034-curated-workouts-are-catalog-items-at-three-levels.md","filePath":"docs/adr/0034-curated-workouts-are-catalog-items-at-three-levels.md"}'),r={name:"docs/adr/0034-curated-workouts-are-catalog-items-at-three-levels.md"};function n(i,e,l,d,h,c){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="curated-workouts-are-catalog-items-at-three-levels" tabindex="-1">Curated workouts are catalog items at three levels <a class="header-anchor" href="#curated-workouts-are-catalog-items-at-three-levels" aria-label="Permalink to &quot;Curated workouts are catalog items at three levels&quot;">​</a></h1><p>The catalog held only exercises (<a href="./0033-the-server-database-is-the-catalog-and-nothing-ships-bundled">ADR 0033</a>). It also offers <strong>curated workouts</strong>: ready-made workouts at different levels. The shape was set by looking at how a personalised training app organises its sessions, without borrowing its names or content, and decided by the maintainer.</p><h2 id="the-decision" tabindex="-1">The decision <a class="header-anchor" href="#the-decision" aria-label="Permalink to &quot;The decision&quot;">​</a></h2><ul><li><strong>A curated workout is a catalog item</strong>, held in the server database beside the exercises. The admin writes, publishes and retires it, and it has a slug that never changes and numbered revisions (<a href="./0030-the-catalog-changes-by-exercise-revision-not-by-catalog-version">ADR 0030</a>). Phones download it item by item, without an account, and it is always available, like an exercise.</li><li><strong>It is always in the list, with nothing to save.</strong> A person starts it directly. It stays in step with the catalog&#39;s latest revision, as an exercise does. Editing it makes a personal copy that no longer follows the catalog, as editing a synced shared plan does (<a href="./0009-shared-plans-are-synced-or-copied">ADR 0009</a>). A copy never changes.</li><li><strong>Curated and personal share one list.</strong> Workouts, and likewise plans, show in a single list on the phone. A <strong>Curated</strong> badge marks the catalog ones, and the list filters by origin (curated or mine) and by level.</li><li><strong>Workouts and plans both have a level</strong>, one of three fixed ones, the same for every goal and named starter, steady and strong until the brand pages settle the words. A curated one always has a level; a person&#39;s own can have one, which they set. A person picks a level; nothing suggests one.</li><li><strong>One workout per level.</strong> The same workout at three levels is three curated workouts, grouped in a workout family, so each level can change its exercises, reps, rests and rounds freely. Swapping exercises by level would need new engine logic and is not done.</li><li><strong>The first version is a browsable list by level.</strong> The admin writes about ten families to start.</li></ul><h2 id="plans" tabindex="-1">Plans <a class="header-anchor" href="#plans" aria-label="Permalink to &quot;Plans&quot;">​</a></h2><p>Catalog plans (<a href="https://github.com/tkint/coach-poulpy/issues/17" target="_blank" rel="noreferrer">#17</a>) already work this way under ADR 0009, and an enrollment pins one plan version. Curated workouts take the same save, sync and copy rule; plans get a level the same way as workouts.</p><h2 id="left-out-of-the-first-version" tabindex="-1">Left out of the first version <a class="header-anchor" href="#left-out-of-the-first-version" aria-label="Permalink to &quot;Left out of the first version&quot;">​</a></h2><p>Suggesting a level from a questionnaire, an effort rating after a session, filters by time or equipment, and catalog plans, which come with #17. Each is its own decision later.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The catalog&#39;s revision, retire and offer-again rules apply to curated workouts unchanged. A retired curated workout stays so copies and sessions still open.</li><li>A curated workout uses exercises by slug. Retiring an exercise a curated workout uses needs the admin to see the workouts it affects.</li><li>A session keeps the revision it was done against, as with a plan version, so a catalog fix never rewrites history.</li><li>The workout and plan lists need an origin badge and filter, and a level filter: a mockup is needed before building. Whether a person&#39;s own item can go without a level is left to it.</li></ul>',10)])])}const p=a(r,[["render",n]]);export{g as __pageData,p as default};
